// @vitest-environment jsdom
// Home's hero art as a static manifest (liveworkspace/docs/site.md "The Explorer"): the template previews
// HeroTemplateFan draws, written beside the templates as @livediagram/templates/hero.json so liveworkspace.app's
// Explorer draws the same art without any of this editor's code (@liveworkspace/explorer HeroArt, generated by
// @liveworkspace/explorer/hero-manifest). This test is the generator and its guard: run with HERO_WRITE=1 to write
// it; without, it fails when the file has drifted from the pictures.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { HERO_MANIFEST_MAX_BYTES, heroArtManifest } from '@liveworkspace/explorer/hero-manifest';
import { HERO_TEMPLATES_LABEL, heroSheets } from './HeroTemplateFan';

// From the editor's folder, where its tests run (jsdom's import.meta.url is not a file address).
const FILE = resolve(process.cwd(), '../../packages/templates/hero.json');

const heroManifest = () => heroArtManifest('livediagram', HERO_TEMPLATES_LABEL, heroSheets());

describe('the hero manifest', () => {
  it('matches the pictures (HERO_WRITE=1 writes it)', () => {
    const text = `${JSON.stringify(heroManifest())}\n`;
    if (process.env.HERO_WRITE === '1') writeFileSync(FILE, text);
    expect(readFileSync(FILE, 'utf8')).toBe(text);
    expect(text.length).toBeLessThan(HERO_MANIFEST_MAX_BYTES);
  });

  it('draws the three templates, the flowchart in front, as data alone', () => {
    const m = heroManifest();
    expect(m.sheets.map((s) => s.id)).toEqual(['mindmap', 'retrospective', 'flowchart']);
    expect(JSON.stringify(m)).not.toMatch(/"on[A-Z]|dangerouslySetInnerHTML|<script/);
  });
});
